parameters.jsCode:
// Zalo OA broadcast is NOT auto-published in v1.
//
// Background: ZaloCRM's public API `/api/public/messages/send` only sends a
// message into an *existing thread* (`{ zaloAccountId, threadId, content }`).
// It has no endpoint to broadcast to OA followers. Zalo's own OpenAPI
// broadcast (message/promotion, broadcast/message) requires pre-approved
// templates, a dedicated OA access_token, and Zalo Business verification.
//
// Until a proper broadcast integration is built, we surface Zalo OA drafts as
// an explicit 'manual_broadcast_required' failure so that:
//   - drafts are not silently left in 'scheduled' forever;
//   - the Telegram alert fans editors over to the Zalo Business dashboard;
//   - operators can UPDATE content.drafts SET status='published' manually
//     after broadcasting.
//
// Workflow 06 already removed zalo_oa from its platform plan in v3, so this
// branch only fires for legacy drafts or drafts created manually. See
// docs/12-zalo-oa-publish.md.
return [{ json: {
  error: {
    code: 'MANUAL_BROADCAST_REQUIRED',
    message: 'Zalo OA broadcast chưa được tự động hoá trong v1. Editor vui lòng broadcast thủ công qua Zalo Business.'
  },
  statusCode: 501
}}];

// Fallback branch for Route by platform. Fires when a draft carries a
// platform string that no explicit output matches (e.g. someone inserted
// 'instagram' via admin SQL before the workflow learned about it).
//
// We funnel this through the same Normalize response → Log + mark outcome
// pipeline so that:
//   - the draft gets a deterministic terminal state ('failed'),
//   - publish_log captures the mismatch with a distinct error code, and
//   - Telegram alert fires so ops can either add the platform handler or
//     clean up the DB row.
const draft = $json;
return [{ json: {
  error: {
    code: 'UNSUPPORTED_PLATFORM',
    message: `Draft ${draft.id} has unsupported platform='${draft.platform}'. No publisher branch exists in WF02.`
  },
  statusCode: 500
}}];

// Classify each publish response into one of three outcomes:
//   outcome='success'          → real publish OK, flip to published.
//   outcome='manual_required'  → operational gate (e.g. Zalo OA has no
//                                broadcast endpoint in v1). NOT a failure —
//                                it is work that has to be done by humans.
//                                Kept separate from failure metrics so the
//                                publish_success_ratio dashboard stays clean.
//   outcome='failed'           → real failure (HTTP 4xx/5xx, throw, etc.).
//
// Error codes treated as manual-required gates (extend as more channels are
// stubbed out the same way):
const MANUAL_CODES = new Set(['MANUAL_BROADCAST_REQUIRED']);
const draft = $('Split per draft').item.json;
const resp  = $input.first().json;
const httpCode = $input.first().headers?.['x-status-code'] ?? ($input.first().statusCode ?? 200);
const hasError = Boolean(resp.error) || (resp.statusCode && resp.statusCode >= 400);
const errorCode = resp.error?.code ? String(resp.error.code) : (hasError ? 'http_error' : null);
let outcome;
if (!hasError) outcome = 'success';
else if (errorCode && MANUAL_CODES.has(errorCode)) outcome = 'manual_required';
else outcome = 'failed';
return [{ json: {
  draftId: draft.id,
  platform: draft.platform,
  outcome,
  ok: outcome === 'success',
  isManual: outcome === 'manual_required',
  isFailed: outcome === 'failed',
  externalId: resp.id || resp.data?.id || resp.post_id || null,
  errorCode,
  errorMessage: resp.error?.message || resp.message || null,
  httpCode
}}];

parameters.jsonBody:
={
  "chat_id": "{{ $env.TELEGRAM_ALERT_CHAT_ID }}",
  "parse_mode": "Markdown",
  "text": "*Manual broadcast required*\nPlatform: {{ $json.platform }}\nDraft: {{ $json.draftId }}\nReason: {{ $json.errorCode }}\nEditor: broadcast thủ công qua Zalo Business, sau đó UPDATE content.drafts SET status='published', external_id='<post_id>' WHERE id='{{ $json.draftId }}';"
}
